<script>
const API_URL = new URL('api.php', window.location.href).toString();
let token = localStorage.getItem('koyo_admin_token') || '';
let currentUser = null, dashboardData = null, umkmTimer = null;
const $ = id => document.getElementById(id);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num = v => new Intl.NumberFormat('id-ID').format(Number(v || 0));
const money = v => v === null || v === undefined || v === '' ? '—' : 'Rp ' + num(v);
function toast(msg){$('toast').textContent=msg;$('toast').classList.remove('hidden');setTimeout(()=>$('toast').classList.add('hidden'),2600)}
function setError(msg){$('globalError').textContent=msg;$('globalError').classList.remove('hidden')}
async function api(action, method='GET', body=null, auth=true, params={}){
 const url=new URL(API_URL);url.searchParams.set('action',action);Object.entries(params).forEach(([k,v])=>url.searchParams.set(k,v));
 const headers={'Accept':'application/json'};if(body!==null)headers['Content-Type']='application/json';if(auth&&token)headers['Authorization']='Bearer '+token;
 let res;try{res=await fetch(url,{method,headers,body:body===null?undefined:JSON.stringify(body),credentials:'same-origin'});}catch(e){throw new Error('Tidak dapat terhubung ke API. Periksa alamat api.php dan koneksi hosting.');}
 let json;try{json=await res.json()}catch(e){throw new Error('API tidak mengembalikan JSON. Periksa error PHP pada server.')}
 if(!res.ok||json.success!==true)throw new Error(json.message||'Permintaan gagal ('+res.status+').');return json.data;
}
function showLogin(msg=''){ $('appView').classList.add('hidden');$('loginView').classList.remove('hidden');if(msg){$('loginError').textContent=msg;$('loginError').classList.remove('hidden')} }
function showApp(){ $('loginView').classList.add('hidden');$('appView').classList.remove('hidden'); }
$('loginForm').addEventListener('submit',async e=>{e.preventDefault();$('loginBtn').disabled=true;$('loginBtn').textContent='Memeriksa akun...';$('loginError').classList.add('hidden');try{
 const d=await api('login','POST',{email:$('email').value.trim(),password:$('password').value,role:'platform_admin'},false);
 if(!d.token)throw new Error('Token login tidak ditemukan.');if(d.role!=='platform_admin')throw new Error('Akun ini bukan Platform Admin. Role akun: '+d.role);
 token=d.token;localStorage.setItem('koyo_admin_token',token);await boot();
 }catch(err){showLogin(err.message)}finally{$('loginBtn').disabled=false;$('loginBtn').textContent='Masuk ke Dashboard →'}});
$('logoutBtn').addEventListener('click',()=>{token='';currentUser=null;localStorage.removeItem('koyo_admin_token');showLogin();$('password').value=''});
async function boot(){try{currentUser=await api('me');if(currentUser.role!=='platform_admin')throw new Error('Akses khusus Platform Admin.');$('adminName').textContent=currentUser.email||'Administrator';$('avatar').textContent=(currentUser.email||'A').charAt(0).toUpperCase();showApp();await loadAll()}catch(e){token='';localStorage.removeItem('koyo_admin_token');showLogin(e.message)}}
function toggleMenu(force){const open=force===undefined?!$('sidebar').classList.contains('open'):force;$('sidebar').classList.toggle('open',open);$('overlay').classList.toggle('show',open)}
document.querySelectorAll('.nav button[data-page]').forEach(b=>b.addEventListener('click',()=>{showPage(b.dataset.page);toggleMenu(false)}));
function showPage(page){document.querySelectorAll('.nav button[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));document.querySelectorAll('.section').forEach(s=>s.classList.remove('active'));const target=$('page-'+page);if(!target)return;target.classList.add('active');if(page==='umkm')loadUmkm();if(page==='evaluations')loadEvaluations();if(page==='periods')loadPeriods();if(page==='leaderboard')loadLeaderboard();if(page==='analytics')loadAnalytics();if(page==='activity')loadActivity();if(page==='attention')loadAttention();}
async function loadAll(){ $('globalError').classList.add('hidden');try{dashboardData=await api('dashboard');renderStats(dashboardData.stats||{});renderChart(dashboardData.results||[]);try{const directory=await api('umkm_list','GET',null,true,{limit:6,offset:0,search:''});renderRecent(directory.rows||[])}catch(e){renderRecent([])}await loadFactors();}catch(e){setError(e.message)}}
function renderStats(s){const items=[['Total UMKM',s.total_umkm,'▤','Terdaftar pada platform'],['UMKM Aktif',s.active_umkm,'✓','Status aktif'],['Owner',s.total_owner,'♙','Akun pemilik usaha'],['Pegawai',s.total_employee,'♧','Akun pegawai'],['Akun Aktif',s.active_users,'●','Owner dan pegawai aktif'],['Evaluasi Tersimpan',s.total_evaluations,'◫','Hasil evaluasi tercatat'],['Periode Evaluasi',s.total_periods,'◷','Seluruh periode']];$('stats').innerHTML=items.map(([label,value,icon,sub])=>`<article class="stat"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon}</span></div><strong>${num(value)}</strong><small>${sub}</small></article>`).join('')}
function renderRecent(rows){$('recentUmkm').innerHTML=rows.length?rows.slice(0,6).map(r=>`<tr><td><strong>${esc(r.name||'—')}</strong></td><td>${esc(r.owner_email||'—')}</td><td>${esc(r.lokasi||'—')}</td><td>${esc(r.sektor||'—')}</td><td><span class="pill ${Number(r.is_active)===1?'':'muted'}">${Number(r.is_active)===1?'Aktif':'Nonaktif'}</span></td></tr>`).join(''):'<tr><td colspan="5" class="empty">Belum ada data UMKM.</td></tr>'}
function renderChart(rows){const labels=rows.slice(0,7).reverse();if(!labels.length){$('resultChart').innerHTML='<div class="empty">Belum ada hasil evaluasi.</div>';return}const max=Math.max(5,...labels.map(r=>Number(r.score_on_5||0)));$('resultChart').innerHTML=labels.map((r,i)=>`<div class="bar-col"><div class="bar" title="${esc(r.umkm_name)}: ${esc(r.score_on_5)}" style="height:${Math.max(4,Number(r.score_on_5||0)/max*175)}px"></div><span class="bar-label">${i+1}</span></div>`).join('')}
const factorNames={INS:'Sumber Daya Kelembagaan',OV:'Nilai Organisasi',LDI:'Keterlibatan Kepemimpinan',WEQ:'Kualitas Lingkungan Kerja',OPS:'Inovasi — Operational Stability',ECT:'Konektivitas Ekonomi'};
async function loadFactors(){try{const rows=await api('factor_averages');const map={};rows.forEach(r=>map[String(r.factor_key).toUpperCase()]=Number(r.avg_score||0));$('factorList').innerHTML=Object.keys(factorNames).map(k=>{const v=(map[k]||0)*5;return `<div class="factor-row"><b>${factorNames[k]}</b><span>${v.toFixed(2)} / 5</span><div class="track"><i style="width:${Math.max(0,Math.min(100,v/5*100))}%"></i></div></div>`}).join('')}catch(e){$('factorList').innerHTML=`<div class="error">${esc(e.message)}</div>`}}
async function loadUmkm(){const q=$('umkmSearch').value.trim();$('umkmRows').innerHTML='<tr><td colspan="6" class="loading">Memuat data...</td></tr>';try{const d=await api('umkm_list','GET',null,true,{limit:100,offset:0,search:q});$('umkmCount').textContent=`Menampilkan ${num(d.rows?.length||0)} dari ${num(d.total||0)} UMKM`;$('umkmRows').innerHTML=(d.rows||[]).length?d.rows.map(r=>`<tr><td><strong>${esc(r.name)}</strong></td><td>${esc(r.owner_email||'—')}</td><td>${esc(r.lokasi||'—')}</td><td>${esc(r.sektor||'—')}</td><td>${money(r.omzet)}</td><td><span class="pill ${Number(r.is_active)===1?'':'muted'}">${Number(r.is_active)===1?'Aktif':'Nonaktif'}</span></td></tr>`).join(''):'<tr><td colspan="6" class="empty">UMKM tidak ditemukan.</td></tr>'}catch(e){$('umkmRows').innerHTML=`<tr><td colspan="6" class="error">${esc(e.message)}</td></tr>`}}
function debouncedUmkm(){clearTimeout(umkmTimer);umkmTimer=setTimeout(loadUmkm,300)}
$('globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){showPage('umkm');$('umkmSearch').value=e.target.value;loadUmkm()}});
async function loadEvaluations(){ $('evaluationRows').innerHTML='<tr><td colspan="6" class="loading">Memuat data...</td></tr>';try{const d=await api('dashboard');const rows=d.results||[];$('evaluationRows').innerHTML=rows.length?rows.map(r=>`<tr><td><strong>${esc(r.umkm_name||'—')}</strong></td><td>${esc(r.period_name||'—')}</td><td><b>${Number(r.score_on_5||0).toFixed(2)}</b></td><td>${esc(r.health_category||'—')}</td><td>${num(r.respondent_count)}</td><td><span class="pill">${esc(r.status||'published')}</span></td></tr>`).join(''):'<tr><td colspan="6" class="empty">Belum ada hasil evaluasi.</td></tr>'}catch(e){$('evaluationRows').innerHTML=`<tr><td colspan="6" class="error">${esc(e.message)}</td></tr>`}}
async function loadPeriods(){ $('periodRows').innerHTML='<tr><td colspan="5" class="loading">Memuat data...</td></tr>';try{const rows=await api('periods');$('periodRows').innerHTML=rows.length?rows.map(r=>`<tr><td><strong>${esc(r.umkm_name||'—')}</strong></td><td>${esc(r.period_name||'—')}</td><td><span class="pill ${r.status==='open'?'':'muted'}">${esc(r.status||'—')}</span></td><td>${esc(r.started_at||'—')}</td><td>${esc(r.created_at||'—')}</td></tr>`).join(''):'<tr><td colspan="5" class="empty">Belum ada periode evaluasi.</td></tr>'}catch(e){$('periodRows').innerHTML=`<tr><td colspan="5" class="error">${esc(e.message)}</td></tr>`}}
async function loadLeaderboard(){ $('leaderRows').innerHTML='<tr><td colspan="7" class="loading">Memuat data...</td></tr>';try{const d=await api('leaderboard');$('leaderTitle').textContent='Peringkat UMKM'+(d.period_name?' · '+d.period_name:'');const rows=d.rows||[];$('leaderRows').innerHTML=rows.length?rows.map(r=>`<tr><td class="rank">${r.rank?('#'+r.rank):'—'}</td><td><strong>${esc(r.umkm_name)}</strong></td><td>${esc(r.lokasi||'—')}</td><td>${esc(r.sektor||'—')}</td><td>${r.score_on_5===null?'—':Number(r.score_on_5).toFixed(2)}</td><td>${esc(r.health_category||'Belum dievaluasi')}</td><td>${esc(r.lowest_factor_name||'—')}</td></tr>`).join(''):'<tr><td colspan="7" class="empty">Belum ada data leaderboard.</td></tr>'}catch(e){$('leaderRows').innerHTML=`<tr><td colspan="7" class="error">${esc(e.message)}</td></tr>`}}

let analyticsCache=null;
async function getPlatformSnapshot(){
 const [dash,periods,umkm,factors,leader]=await Promise.all([
  api('dashboard'),api('periods'),api('umkm_list','GET',null,true,{limit:500,offset:0,search:''}),api('factor_averages'),api('leaderboard')
 ]);
 return {dash,periods:periods||[],umkms:umkm.rows||[],factors:factors||[],leader};
}
function categoryLabel(v){return String(v||'Belum dikategorikan').trim()||'Belum dikategorikan'}
async function loadAnalytics(){
 $('analyticsMetrics').innerHTML='<div class="loading">Memuat analitik...</div>';
 try{
  const d=await getPlatformSnapshot();analyticsCache=d;const stats=d.dash.stats||{},results=(d.dash.results||[]).filter(r=>String(r.status||'published').toLowerCase()==='published');
  const average=results.length?results.reduce((a,r)=>a+Number(r.score_on_5||0),0)/results.length:0;
  const metrics=[['Total UMKM',stats.total_umkm,'Seluruh usaha terdaftar'],['UMKM aktif',stats.active_umkm,'Status aktif'],['Hasil terpublikasi',results.length,'Hasil evaluasi tersedia'],['Rata-rata skor',results.length?average.toFixed(2)+' / 5':'—','Hanya hasil terpublikasi'],['Periode evaluasi',stats.total_periods,'Seluruh periode tercatat'],['Akun aktif',stats.active_users,'Owner dan pegawai']];
  $('analyticsMetrics').innerHTML=metrics.map(x=>`<article class="metric-box"><span>${esc(x[0])}</span><b>${esc(x[1])}</b><small>${esc(x[2])}</small></article>`).join('');
  const cats={};results.forEach(r=>{const k=categoryLabel(r.health_category);cats[k]=(cats[k]||0)+1});const total=results.length;
  $('analyticsCategories').innerHTML=total?Object.entries(cats).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="factor-row"><b>${esc(k)}</b><span>${v} · ${Math.round(v/total*100)}%</span><div class="track"><i style="width:${v/total*100}%"></i></div></div>`).join(''):'<div class="empty">Belum ada hasil evaluasi terpublikasi.</div>';
  const names={INS:'Sumber Daya Kelembagaan',OV:'Nilai Organisasi',LDI:'Keterlibatan Kepemimpinan',WEQ:'Kualitas Lingkungan Kerja',OPS:'Inovasi — Operational Stability',ECT:'Konektivitas Ekonomi'};const fmap={};d.factors.forEach(r=>fmap[String(r.factor_key).toUpperCase()]=Number(r.avg_score||0)*5);
  $('analyticsFactors').innerHTML=Object.entries(names).map(([k,n])=>{const v=fmap[k];return `<div class="factor-row"><b>${esc(n)}</b><span>${v===undefined?'—':v.toFixed(2)+' / 5'}</span><div class="track"><i style="width:${v===undefined?0:Math.max(0,Math.min(100,v/5*100))}%"></i></div></div>`}).join('');
  $('analyticsReport').innerHTML=`<table><thead><tr><th>Indikator</th><th>Nilai</th><th>Keterangan</th></tr></thead><tbody>${metrics.map(x=>`<tr><td><strong>${esc(x[0])}</strong></td><td>${esc(x[1])}</td><td>${esc(x[2])}</td></tr>`).join('')}</tbody></table>`;
 }catch(e){$('analyticsMetrics').innerHTML=`<div class="error">${esc(e.message)}</div>`;$('analyticsCategories').innerHTML='';$('analyticsFactors').innerHTML='';}
}
function exportAnalyticsCsv(){if(!analyticsCache){toast('Muat analitik terlebih dahulu.');return}const s=analyticsCache.dash.stats||{};const rows=[['Indikator','Nilai'],['Total UMKM',s.total_umkm||0],['UMKM Aktif',s.active_umkm||0],['Owner',s.total_owner||0],['Pegawai',s.total_employee||0],['Akun Aktif',s.active_users||0],['Evaluasi Tersimpan',s.total_evaluations||0],['Periode Evaluasi',s.total_periods||0]];const csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='laporan-platform-VISTRA.csv';a.click();URL.revokeObjectURL(url);}
async function loadAttention(){ $('attentionList').innerHTML='<div class="loading">Memeriksa data...</div>';try{const d=await getPlatformSnapshot();const latestByUmkm={};(d.dash.results||[]).filter(r=>String(r.status||'published').toLowerCase()==='published').forEach(r=>{const id=String(r.umkm_id);if(!latestByUmkm[id])latestByUmkm[id]=r});const latestPeriod={};d.periods.forEach(p=>{const id=String(p.umkm_id);if(!latestPeriod[id]||Number(p.id)>Number(latestPeriod[id].id))latestPeriod[id]=p});const pending=d.umkms.filter(u=>{const p=latestPeriod[String(u.id)];if(!p)return false;const r=latestByUmkm[String(u.id)];return !r||Number(r.period_id)!==Number(p.id)});$('attentionSummary').textContent=`${pending.length} UMKM dari ${d.umkms.length} UMKM memiliki periode terbaru tanpa hasil terpublikasi.`;$('attentionList').innerHTML=pending.length?pending.map(u=>{const p=latestPeriod[String(u.id)];return `<div class="attention-item"><div><b>${esc(u.name||'UMKM')}</b><small>${esc(p?.period_name||'Periode terbaru')} · Status periode: ${esc(p?.status||'—')}</small></div><span class="pill warn">Perlu dipantau</span></div>`}).join(''):'<div class="empty">Tidak ada UMKM yang perlu ditindaklanjuti berdasarkan data periode dan hasil terpublikasi saat ini.</div>'}catch(e){$('attentionList').innerHTML=`<div class="error">${esc(e.message)}</div>`}}
async function loadActivity(){ $('activityList').innerHTML='<div class="loading">Memuat aktivitas...</div>';try{const d=await getPlatformSnapshot();const items=[];d.umkms.forEach(u=>{if(u.created_at)items.push({date:u.created_at,icon:'＋',title:'UMKM terdaftar',detail:u.name||'Nama UMKM tidak tersedia'})});d.periods.forEach(p=>{if(p.created_at||p.started_at)items.push({date:p.created_at||p.started_at,icon:'◷',title:'Periode evaluasi dibuat',detail:(p.umkm_name||'UMKM')+' · '+(p.period_name||'Periode')})});(d.dash.results||[]).forEach(r=>{const date=r.calculated_at||r.published_at||r.created_at;if(date)items.push({date,icon:'✓',title:'Hasil evaluasi tercatat',detail:(r.umkm_name||'UMKM')+' · '+(r.period_name||'Periode')+' · '+(Number(r.score_on_5||0).toFixed(2))+'/5'})});items.sort((a,b)=>new Date(String(b.date).replace(' ','T'))-new Date(String(a.date).replace(' ','T')));$('activityList').innerHTML=items.length?items.slice(0,60).map(x=>`<div class="activity-item"><div class="activity-dot">${esc(x.icon)}</div><div><b>${esc(x.title)}</b><small>${esc(x.detail)} · ${esc(x.date)}</small></div></div>`).join(''):'<div class="empty">Belum ada aktivitas bertanggal yang dapat ditampilkan.</div>'}catch(e){$('activityList').innerHTML=`<div class="error">${esc(e.message)}</div>`}}

if(token)boot();
</script>
</body></html>
